class ManagedInstallation:
    def __init__(self, installation_root: str | Path, project_dir: str | Path) -> None:
        requested_root = Path(installation_root).expanduser().absolute()
        _ordinary_install_path(requested_root, directory=True)
        self.root = requested_root.resolve()
        self.project = Path(project_dir).expanduser().resolve()
        if self.root == self.project or self.root.is_relative_to(self.project) or self.project.is_relative_to(self.root):
            raise ManagedInstallationError("installation_scope_invalid", "受管安装目录与项目目录必须互不包含")

    @staticmethod
    def inspect(wheel_path: str | Path) -> dict[str, Any]:
        wheel = Path(wheel_path).expanduser().resolve()
        if not wheel.is_file():
            raise ManagedInstallationError("invalid_upgrade_wheel", "目标 wheel 不存在")
        hashes: dict[str, str] = {}
        try:
            with ZipFile(wheel) as archive:
                entries = archive.infolist()
                if len(entries) > 10000 or sum(entry.file_size for entry in entries) > 512 * 1024 * 1024:
                    raise ValueError("archive limits")
                seen = set()
                metadata_names = []
                for entry in entries:
                    name = entry.filename.rstrip("/")
                    relative = PurePosixPath(name)
                    if not name or relative.is_absolute() or ".." in relative.parts or "\\" in name or ":" in name or relative.as_posix() != name or name.casefold() in seen:
                        raise ValueError("unsafe or duplicate archive name")
                    seen.add(name.casefold())
                    if not (relative.parts[0] == "strixnova" or relative.parts[0].startswith("strixnova-") and relative.parts[0].endswith(".dist-info")):
                        raise ValueError("unexpected wheel root")
                    if entry.is_dir():
                        continue
                    if entry.file_size > 64 * 1024 * 1024:
                        raise ValueError("file limit")
                    if name.endswith(".dist-info/METADATA"):
                        metadata_names.append(name)
                    if name.startswith("strixnova/"):
                        hashes[name[len("strixnova/"):]] = hashlib.sha256(archive.read(entry)).hexdigest()
                if len(metadata_names) != 1:
                    raise ValueError("metadata count")
                metadata = Parser().parsestr(archive.read(metadata_names[0]).decode("utf-8"))
                if str(metadata.get("Name", "")).casefold() != "strixnova" or not metadata.get("Version"):
                    raise ValueError("package identity")
                wheel_metadata = Parser().parsestr(archive.read(metadata_names[0].removesuffix("METADATA") + "WHEEL").decode("utf-8"))
                if wheel_metadata.get("Root-Is-Purelib", "").casefold() != "true" or "py3-none-any" not in wheel_metadata.get_all("Tag", []):
                    raise ValueError("unsupported wheel platform")
                entrypoints = ConfigParser(interpolation=None)
                entrypoints.read_string(archive.read(metadata_names[0].removesuffix("METADATA") + "entry_points.txt").decode("utf-8"))
                if entrypoints.get("console_scripts", "strixnova") != "strixnova.cli:main":
                    raise ValueError("unexpected command entry")
                contract = validate_compatibility(json.loads(archive.read("strixnova/resources/" + COMPATIBILITY_RESOURCE)))
                if "resources/agent-skill/strixnova/SKILL.md" not in hashes or "__init__.py" not in hashes:
                    raise ValueError("required package content")
        except (OSError, BadZipFile, ValueError, KeyError, UnicodeError, RuntimeIdentityError, ConfigParserError) as error:
            raise ManagedInstallationError("invalid_upgrade_wheel", "目标 wheel 的路径、包身份或运行合同无效") from error
        return {
            "schema_version": "strixnova.installation-target.v1", "wheel_path": str(wheel),
            "wheel_sha256": file_sha256(wheel), "version": str(metadata["Version"]),
            **content_identities(hashes), "formats": contract["formats"],
            "dependency_lock_sha256": contract["dependency_lock"]["sha256"],
            "requires_python": str(metadata.get("Requires-Python", "")),
            "unpacked_size_bytes": sum(entry.file_size for entry in entries),
        }

    def _dependency_space(self, wheelhouse: Path | None, requirements: str) -> int:
        expected = locked_dependencies(requirements)
        if not expected:
            return 0
        if wheelhouse is None or not wheelhouse.is_dir():
            raise ManagedInstallationError("installation_wheelhouse_required", "需要明确的本地依赖 wheel 目录")
        found: set[str] = set()
        expanded = 0
        try:
            for wheel in sorted(wheelhouse.glob("*.whl")):
                if wheel.is_symlink() or not wheel.is_file():
                    raise ValueError("nonregular dependency wheel")
                digest = file_sha256(wheel)
                packages = {name for name, hashes in expected.items() if digest in hashes}
                if not packages:
                    continue
                with ZipFile(wheel) as archive:
                    entries = archive.infolist()
                    size = sum(entry.file_size for entry in entries)
                    if len(entries) > 20000 or size > 2 * 1024 ** 3:
                        raise ValueError("dependency expansion limit")
                    expanded += size
                found.update(packages)
        except (OSError, ValueError, BadZipFile) as error:
            raise ManagedInstallationError("installation_dependencies_invalid", "本地依赖 wheel 不是可核验的受限归档") from error
        if found != set(expected):
            raise ManagedInstallationError("installation_dependencies_missing", "本地 wheel 目录缺少锁定依赖", details={"packages": sorted(set(expected) - found)})
        return expanded

    @staticmethod
    def _run(command: list[str], *, cwd: Path, timeout: float = 600, log_root: Path | None = None, check: bool = True) -> ProcessResult:
        environment = _environment()
        run_root = None
        if log_root is not None:
            _ordinary_install_path(log_root, directory=True)
            log_root.mkdir(parents=True, exist_ok=True)
            run_root = log_root / uuid.uuid4().hex
            run_root.mkdir()
            temporary = run_root / "temporary"
            temporary.mkdir()
            environment.update({key: str(temporary) for key in ("TMP", "TEMP", "TMPDIR")})
        try:
            result = run_process(command, cwd=cwd,
                policy=ProcessPolicy.exact("strixnova-managed-installation-v1", "执行明确选择的本地安装或运行检查", command),
                limits=ProcessLimits(timeout_seconds=timeout), env=environment)
        except ProcessExecutionError as error:
            raise ManagedInstallationError("installation_process_blocked", str(error), details={"reason": error.reason}) from error
        if run_root is not None:
            (run_root / "stdout.log").write_bytes(result.stdout)
            (run_root / "stderr.log").write_bytes(result.stderr)
            write_maintenance_json(run_root / "receipt.json", {"command": command, "exit_code": result.exit_code, "duration_seconds": result.duration_seconds, "stdout_sha256": hashlib.sha256(result.stdout).hexdigest(), "stderr_sha256": hashlib.sha256(result.stderr).hexdigest()})
        if check and result.exit_code != 0:
            raise ManagedInstallationError("installation_command_failed", "安装或实际运行检查失败", details={"exit_code": result.exit_code, "stderr": result.stderr_text()[-3000:], "stdout": result.stdout_text()[-1000:]})
        return result

    @staticmethod
    def probe(python_path: str | Path) -> dict[str, Any]:
        python = Path(python_path).expanduser().resolve()
        if not python.is_file():
            raise ManagedInstallationError("installation_python_missing", "指定解释器不存在")
        result = ManagedInstallation._run([str(python), "-I", "-B", "-X", "utf8", "-c", _PROBE], cwd=python.parent, timeout=30)
        try:
            value = json.loads(result.stdout)
            if value["python_version"] != [3, 12] or (value["authority_format"] != AUTHORITY_FORMAT or value["activity_format"] != ACTIVITY_FORMAT) or not value["entrypoint_sha256"]:
                raise ValueError
            if not (Path(value["skill_path"]) / "SKILL.md").is_file():
                raise ValueError
            return value
        except (ValueError, KeyError, TypeError) as error:
            raise ManagedInstallationError("installed_runtime_invalid", "实际程序、Python、原生入口或配套 Skill 不满足受支持运行合同") from error

    def _validate_root(self, *, create: bool = False) -> None:
        _ordinary_install_path(self.root, directory=True)
        for path in (self.root, self.root / "versions", self.root / "active.json", self.root / "owner.json"):
            if path.is_symlink() or path.is_junction():
                raise ManagedInstallationError("installation_path_unsafe", "受管安装位置不能是链接")
        if self.root.exists() and not self.root.is_dir():
            raise ManagedInstallationError("installation_path_occupied", "安装根不是目录")
        owner = self.root / "owner.json"
        if owner.exists():
            try:
                value = json.loads(owner.read_text(encoding="utf-8"))
                if value != {"schema_version": "strixnova.installation-owner.v1", "project": str(self.project)}:
                    raise ValueError
            except (OSError, ValueError, TypeError) as error:
                raise ManagedInstallationError("installation_owner_mismatch", "该安装根不属于当前项目") from error
        elif self.root.exists() and any(self.root.iterdir()):
            raise ManagedInstallationError("installation_path_occupied", "不接管没有所有权记录的非空安装目录")
        elif create:
            self.root.mkdir(parents=True, exist_ok=True)
            with owner.open("x", encoding="utf-8", newline="\n") as output:
                json.dump({"schema_version": "strixnova.installation-owner.v1", "project": str(self.project)}, output, ensure_ascii=False, sort_keys=True)
                output.flush()
                os.fsync(output.fileno())

    def active(self) -> dict[str, Any] | None:
        self._validate_root()
        path = self.root / "active.json"
        if not path.exists():
            return None
        try:
            if path.stat().st_size > 1024 * 1024:
                raise ValueError
            value = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(value, dict) or set(value) != {"schema_version", "project", "upgrade_id", "runtime"} or value["schema_version"] != "strixnova.runtime-selection.v1" or value["project"] != str(self.project):
                raise ValueError
            runtime = value["runtime"]
            if not isinstance(value["upgrade_id"], str) or not value["upgrade_id"] or not isinstance(runtime, dict):
                raise ValueError
            if any(not isinstance(runtime.get(key), str) or not runtime[key] for key in ("python_path", "entrypoint", "build_sha256", "skill_sha256")):
                raise ValueError
            if type(runtime.get("authority_format")) is not int or runtime["authority_format"] != AUTHORITY_FORMAT or type(runtime.get("activity_format")) is not int or runtime["activity_format"] != ACTIVITY_FORMAT:
                raise ValueError
            return value
        except (OSError, ValueError, KeyError, TypeError) as error:
            raise ManagedInstallationError("installation_selection_invalid", "当前运行选择损坏") from error

    def plan(
        self, wheel: str | Path, *, source_python: str | Path | None = None,
        builder_python: str | Path | None = None, wheelhouse: str | Path | None = None,
    ) -> dict[str, Any]:
        self._validate_root()
        target = self.inspect(wheel)
        previous = self.active()
        source = self.probe(source_python or (previous["runtime"]["python_path"] if previous else sys.executable))
        if previous and previous["runtime"] != source:
            raise ManagedInstallationError("installation_source_mismatch", "源运行程序必须与当前受管选择一致")
        builder = Path(builder_python or sys.executable).expanduser().resolve()
        if not builder.is_file():
            raise ManagedInstallationError("installation_python_missing", "创建隔离环境的解释器不存在")
        builder_info = self._run([str(builder), "-I", "-B", "-S", "-c", "import json,sys; print(json.dumps(list(sys.version_info[:2])))"], cwd=self.project, timeout=30)
        if json.loads(builder_info.stdout) != [3, 12]:
            raise ManagedInstallationError("installation_python_unsupported", "目标环境必须使用 Python 3.12")
        wheelhouse_path = Path(wheelhouse).expanduser().resolve() if wheelhouse is not None else None
        if wheelhouse_path is not None and not wheelhouse_path.is_dir():
            raise ManagedInstallationError("installation_wheelhouse_missing", "本地依赖 wheel 目录不存在")
        dependencies = {}
        if wheelhouse_path:
            for path in sorted(wheelhouse_path.glob("*.whl")):
                if path.is_symlink():
                    raise ManagedInstallationError("installation_path_unsafe", "依赖 wheel 不能是链接")
                dependencies[path.name] = file_sha256(path)
        with ZipFile(Path(target["wheel_path"])) as archive:
            requirements = json.loads(archive.read("strixnova/resources/" + COMPATIBILITY_RESOURCE))["dependency_lock"]["requirements"]
        expanded_dependencies = self._dependency_space(wheelhouse_path, requirements)
        return {
            "schema_version": "strixnova.managed-installation-plan.v1", "installation_root": str(self.root),
            "target": target, "source_runtime": source, "previous_selection": previous,
            "builder_python": str(builder), "builder_sha256": file_sha256(builder),
            "required_storage_bytes": 128 * 1024 * 1024 + 3 * (target["unpacked_size_bytes"] + expanded_dependencies),
            "wheelhouse": str(wheelhouse_path) if wheelhouse_path else None, "dependency_wheels": dependencies,
            "request": {"installation_root": str(self.root), "target_wheel": str(Path(wheel).expanduser().resolve()), "source_python": source["python_path"], "builder_python": str(builder), "wheelhouse": str(wheelhouse_path) if wheelhouse_path else None},
        }

    @_installation_write
    def prepare(
        self, target: dict[str, Any], *, builder_python: str | Path | None = None,
        wheelhouse: str | Path | None = None,
    ) -> dict[str, Any]:
        if not isinstance(target, dict) or self.inspect(target.get("wheel_path", "")) != target:
            raise ManagedInstallationError("installation_target_changed", "目标 wheel 自预检后已经改变")
        wheel = Path(target["wheel_path"])
        with ZipFile(wheel) as archive:
            contract = validate_compatibility(json.loads(archive.read("strixnova/resources/" + COMPATIBILITY_RESOURCE)))
        requirements = contract["dependency_lock"]["requirements"]
        has_dependencies = any(line.strip() and not line.lstrip().startswith("#") for line in requirements.splitlines())
        wheelhouse_path = Path(wheelhouse).expanduser().resolve() if wheelhouse is not None else None
        if has_dependencies and (wheelhouse_path is None or not wheelhouse_path.is_dir()):
            raise ManagedInstallationError("installation_wheelhouse_required", "需要本地依赖 wheel 目录；安装过程不自动访问包索引")
        expanded_dependencies = self._dependency_space(wheelhouse_path, requirements)
        builder = Path(builder_python or sys.executable).expanduser().resolve()
        if not builder.is_file():
            raise ManagedInstallationError("installation_python_missing", "隔离环境创建解释器不存在")
        self._validate_root(create=True)
        directory = self.root / "versions" / target["wheel_sha256"]
        if directory.is_symlink() or directory.is_junction():
            raise ManagedInstallationError("installation_path_unsafe", "目标安装不能是链接")
        marker = directory / "installation.json"
        _ordinary_install_path(marker)
        owner = {"schema_version": "strixnova.prepared-installation.v1", "target": target, "project": str(self.project)}
        if directory.exists():
            try:
                old = json.loads(marker.read_text(encoding="utf-8"))
                if any(old.get(key) != value for key, value in owner.items()):
                    raise ValueError
                if old.get("state") == "ready":
                    if self.probe(old["runtime"]["python_path"]) != old["runtime"]:
                        raise ManagedInstallationError("installed_runtime_changed", "已准备的程序或 Skill 已变化")
                    return old
            except (OSError, ValueError, KeyError, TypeError) as error:
                raise ManagedInstallationError("installation_path_occupied", "目标安装目录没有匹配的创建记录") from error
        else:
            directory.mkdir(parents=True)
            write_maintenance_json(marker, {**owner, "state": "preparing"})
        if shutil.disk_usage(self.root).free < 128 * 1024 * 1024 + 3 * (target["unpacked_size_bytes"] + expanded_dependencies):
            raise ManagedInstallationError("installation_space_insufficient", "准备隔离安装的可用空间不足")
        environment = directory / "venv"
        if environment.is_symlink() or environment.is_junction():
            raise ManagedInstallationError("installation_path_unsafe", "虚拟环境不能是链接")
        logs = directory / "logs"
        _ordinary_install_path(directory / "requirements.txt")
        for relative in ("Scripts", "Lib", "Lib/site-packages", "Lib/site-packages/strixnova") if os.name == "nt" else ("bin", "lib"):
            _ordinary_install_path(environment / relative, directory=True)
        self._run([str(builder), "-I", "-m", "venv", str(environment)], cwd=directory, log_root=logs)
        python = environment / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
        lock = directory / "requirements.txt"
        lock.write_text(requirements, encoding="utf-8", newline="")
        if has_dependencies:
            self._run([str(python), "-I", "-m", "pip", "install", "--no-cache-dir", "--no-index", "--only-binary=:all:", "--require-hashes", "--find-links", str(wheelhouse_path), "-r", str(lock)], cwd=directory, log_root=logs)
        self._run([str(python), "-I", "-m", "pip", "install", "--no-cache-dir", "--no-index", "--no-deps", str(wheel)], cwd=directory, log_root=logs)
        self._run([str(python), "-I", "-m", "pip", "check"], cwd=directory, log_root=logs)
        runtime = self.probe(python)
        for key in ("version", "build_sha256", "skill_sha256"):
            if runtime[key] != target[key]:
                raise ManagedInstallationError("installed_runtime_mismatch", "实际程序或配套 Skill 与目标 wheel 不一致")
        if runtime["authority_format"] != target["formats"]["authority"]:
            raise ManagedInstallationError("installed_runtime_mismatch", "实际程序的格式支持与目标声明不一致")
        ready = {**owner, "state": "ready", "runtime": runtime, "logs_directory": str(logs)}
        write_maintenance_json(marker, ready)
        return ready

    @_installation_write
    def select(self, runtime: dict[str, Any], *, upgrade_id: str, expected: dict[str, Any] | None) -> dict[str, Any]:
        self._validate_root(create=True)
        if self.active() != expected:
            raise ManagedInstallationError("installation_selection_changed", "当前运行选择自预检后已经变化")
        if self.probe(runtime["python_path"]) != runtime:
            raise ManagedInstallationError("installed_runtime_changed", "待选择的程序或 Skill 已变化")
        selection = {"schema_version": "strixnova.runtime-selection.v1", "project": str(self.project), "upgrade_id": upgrade_id, "runtime": runtime}
        write_maintenance_json(self.root / "active.json", selection)
        return selection

    def run(self, arguments: list[str], *, timeout: float = 3600) -> ProcessResult:
        selected = self.active()
        if selected is None:
            raise ManagedInstallationError("installation_not_selected", "尚未选择实际运行版本")
        runtime = selected["runtime"]
        if self.probe(runtime["python_path"]) != runtime:
            raise ManagedInstallationError("installed_runtime_changed", "当前运行程序或配套 Skill 已变化")
        command_arguments = list(arguments)
        for index, argument in enumerate(arguments):
            value = arguments[index + 1] if argument == "--project-dir" and index + 1 < len(arguments) else argument.split("=", 1)[1] if argument.startswith("--project-dir=") else None
            if value is None:
                continue
            project = Path(value).expanduser().resolve()
            if project != self.project:
                raise ManagedInstallationError("installation_project_mismatch", "受管运行入口不能代替其他项目选择版本")
            # The child runs in self.project, so pass the absolute path that
            # was validated in the caller's directory.
            if argument == "--project-dir":
                command_arguments[index + 1] = str(project)
            else:
                command_arguments[index] = "--project-dir=" + str(project)
        scope = nullcontext() if arguments and arguments[0] == "upgrade" else project_operation(self.project, writer_format=runtime["authority_format"], activity_format=runtime["activity_format"])
        with scope:
            return self._run([runtime["entrypoint"], *command_arguments], cwd=self.project, timeout=timeout, check=False)

    def validate_project(self, runtime: dict[str, Any], *, upgrade_id: str, expected_snapshot_sha256: str) -> dict[str, Any]:
        """Exercise the actual selected console entry before ending maintenance."""
        command = [runtime["entrypoint"], "upgrade", "validate", "--project-dir", str(self.project), "--upgrade-id", upgrade_id]
        result = self._run(command, cwd=self.project, timeout=60)
        try:
            envelope = json.loads(result.stdout)
            validation = envelope["validation"]
            if envelope.get("ok") is not True or validation["project"] != str(self.project) or validation["upgrade_id"] != upgrade_id:
                raise ValueError
            if validation["build_sha256"] != runtime["build_sha256"] or validation["skill_sha256"] != runtime["skill_sha256"] or validation["database_snapshot_sha256"] != expected_snapshot_sha256:
                raise ValueError
        except (ValueError, KeyError, TypeError) as error:
            raise ManagedInstallationError("installation_trial_invalid", "目标原生入口未返回匹配的项目试读结果") from error
        return {**validation, "actual_entrypoint": runtime["entrypoint"], "stdout_sha256": hashlib.sha256(result.stdout).hexdigest(), "exit_code": result.exit_code}

class RuntimeUpgrade:
    def __init__(self, project_dir: str | Path) -> None:
        self.project = Path(project_dir).expanduser().resolve()
        if not self.project.is_dir():
            raise RuntimeUpgradeError("project_missing", "升级项目目录不存在")
        self.maintenance = ProjectMaintenance(self.project)

    def _sources(self) -> dict[str, Path]:
        authority = self.project / ".strixnova" / "authority.sqlite3"
        paths = {"authority": authority} if authority.exists() or authority.is_symlink() else {}
        activity = self.project / ".strixnova" / "delivery-activities.sqlite3"
        if activity.exists():
            paths["delivery_activities"] = activity
        return paths

    @staticmethod
    def _matches_original_or_fenced(current: Mapping[str, Any], original: Mapping[str, Any]) -> bool:
        if current == original:
            return True
        if current.get("format") != original.get("format") or current.get("data_sha256") != original.get("data_sha256"):
            return False
        extras = [entry for entry in current["schema"] if entry["name"].startswith(MAINTENANCE_TRIGGER_PREFIX)]
        retained = [entry for entry in current["schema"] if not entry["name"].startswith(MAINTENANCE_TRIGGER_PREFIX)]
        tables = {entry["name"] for entry in original["schema"] if entry["type"] == "table"}
        expected = sorted(write_guard_definitions(tables, temporary=True), key=lambda entry: (entry["type"], entry["name"]))
        return retained == original["schema"] and extras == expected

    def _quiesce(self, path: Path) -> None:
        try:
            with closing(sqlite3.connect(path, timeout=0.5, isolation_level=None)) as connection:
                checkpoint = connection.execute("PRAGMA wal_checkpoint(TRUNCATE)").fetchone()
                if checkpoint and checkpoint[0] != 0:
                    raise sqlite3.OperationalError("WAL checkpoint blocked")
                mode = connection.execute("PRAGMA journal_mode=DELETE").fetchone()[0]
                if str(mode).casefold() != "delete":
                    raise sqlite3.OperationalError("journal mode remains active")
                connection.execute("BEGIN EXCLUSIVE")
                connection.rollback()
        except sqlite3.Error as error:
            raise RuntimeUpgradeError("upgrade_connections_open", "仍有数据库连接或写入未退出，不能安全切换；关闭旧客户端后恢复", details={"database": path.name}) from error

    def _fence_sources(self, journal: dict[str, Any]) -> None:
        journal["state"] = "fencing"
        self._save(journal)
        for kind, path in sorted(self._sources().items(), key=lambda entry: entry[0] == "authority"):
            with closing(sqlite3.connect(path, timeout=0.5, isolation_level=None)) as connection:
                connection.execute("BEGIN EXCLUSIVE")
                try:
                    current = _database_snapshot(path, kind, existing_connection=connection)
                    if not self._matches_original_or_fenced(current, journal["plan"]["sources"][kind]):
                        raise RuntimeUpgradeError("upgrade_source_changed", "取得排他写入保护时源数据已经变化")
                    install_write_guards(connection, temporary=True)
                    connection.commit()
                except BaseException:
                    connection.rollback()
                    raise

    def _assets(self) -> dict[str, dict[str, Any]]:
        root = self.project / ".strixnova" / "artifacts"
        values: dict[str, dict[str, Any]] = {}
        for directory, folders, files in os.walk(root, followlinks=False) if root.exists() else ():
            parent = Path(directory)
            if parent == root:
                folders[:] = [name for name in folders if name != "maintenance"]
            for name in [*folders, *files]:
                candidate = parent / name
                if candidate.is_symlink() or candidate.is_junction():
                    raise RuntimeUpgradeError("upgrade_evidence_path_unsafe", "证据目录包含链接，不能安全备份")
            for name in files:
                path = parent / name
                values[path.relative_to(self.project).as_posix()] = {"sha256": _file_digest(path), "size_bytes": path.stat().st_size}
        configuration = self.project / "strixnova-project.yaml"
        if configuration.is_symlink():
            raise RuntimeUpgradeError("upgrade_project_documents_invalid", "项目配置不能是链接")
        if configuration.exists():
            try:
                checker = ProjectAuthorityConsistency(self.project)
                try:
                    authorities = checker.load()
                except ProjectAuthorityConsistencyError:
                    authorities = checker.load_working_tree_candidate(None)
                paths = {"strixnova-project.yaml", checker.baseline_reader.locate().relative_to(self.project).as_posix()}
                for kind in AUTHORITY_KINDS:
                    paths.update(checker.authority_governed_paths(authorities, kind))
                for relative in sorted(paths):
                    target = checker.reader.absolute_path(relative)
                    values[relative] = {"sha256": _file_digest(target), "size_bytes": target.stat().st_size}
            except (ProjectAuthorityConsistencyError, OSError, ValueError) as error:
                raise RuntimeUpgradeError("upgrade_project_documents_invalid", "项目长期文件的格式或精确引用不满足当前程序合同；升级不能隐式改写这些文件", details={"reason": str(error)}) from error
        return values

    def _inspect(self, installation: Mapping[str, Any] | None = None) -> dict[str, Any]:
        self.maintenance._safe_root()
        for relative in (".strixnova/artifacts/document-transactions", ".strixnova/artifacts/implementation-alignment/transactions"):
            transactions = self.project / relative
            if transactions.is_symlink() or transactions.is_junction():
                raise RuntimeUpgradeError("upgrade_pending_document_transaction", "文件事务目录不是普通目录")
            if transactions.exists() and any(transactions.iterdir()):
                raise RuntimeUpgradeError("upgrade_pending_document_transaction", "仍有未收口的文件事务，必须先恢复")
        if (self.project / ".git").exists():
            try:
                pending = GitProjectReader(self.project).pending_operations()
            except GitProjectReaderError as error:
                raise RuntimeUpgradeError("upgrade_git_state_invalid", "无法核验项目真实 Git 状态，不能切换", details={"reason": error.code}) from error
            if pending:
                raise RuntimeUpgradeError("upgrade_pending_git_operation", "仍有未结束的 Git 操作，不能切换", details={"operations": pending})
        sources = {kind: _database_snapshot(path, kind) for kind, path in self._sources().items()}
        if "authority" not in sources:
            raise RuntimeUpgradeError("upgrade_source_invalid", "没有可维护的事项库；新项目应先初始化")
        context = ProjectContextResolver(self.project).configured()
        stored_identity = sources["authority"].get("project_id")
        project_identity = context.project_id if context is not None else stored_identity
        if stored_identity is not None and stored_identity != project_identity:
            raise RuntimeUpgradeError("authority_project_mismatch", "管理库和声明的项目身份不一致，不能覆盖归属")
        interrupted = [record for record in self.maintenance.unclosed_operations() if record["state"] == "interrupted"]
        if interrupted:
            raise RuntimeUpgradeError("upgrade_unclosed_operations", "存在没有结束记录的执行，必须先核验执行停止及实际副作用", details=interrupted)
        target = runtime_identity()
        install_plan = None
        if installation is not None:
            required = {"installation_root", "target_wheel", "source_python", "builder_python", "wheelhouse"}
            if not isinstance(installation, Mapping) or set(installation) != required:
                raise RuntimeUpgradeError("upgrade_installation_request_invalid", "安装升级请求字段不完整")
            manager = ManagedInstallation(installation["installation_root"], self.project)
            install_plan = manager.plan(installation["target_wheel"], source_python=installation["source_python"], builder_python=installation["builder_python"], wheelhouse=installation["wheelhouse"])
            if install_plan["source_runtime"]["authority_format"] != AUTHORITY_FORMAT or install_plan["source_runtime"]["activity_format"] != ACTIVITY_FORMAT:
                raise RuntimeUpgradeError("source_runtime_format_mismatch", "源程序与当前数据格式不匹配")
            declared = install_plan["target"]
            if declared["formats"] != target["formats"]:
                raise RuntimeUpgradeError("unsupported_upgrade_target", "目标程序必须支持当前完整数据格式；本版本不执行格式转换")
            target = {"schema_version": "strixnova.runtime-identity.v1", "identity_source": "wheel_declaration", **{key: declared[key] for key in ("version", "build_sha256", "skill_sha256", "package_file_count", "formats", "dependency_lock_sha256")}}
        plan = {
            "schema_version": "strixnova.runtime-upgrade-plan.v1", "project": str(self.project),
            "source_formats": {kind: value["format"] for kind, value in sources.items()},
            "target_formats": target["formats"], "sources": sources, "assets": self._assets(),
            "target_runtime": target, "project_identity": project_identity,
            "requires_maintenance_window": True,
            "writes_performed": False, "maintenance_revision": self._last_closed(),
            "installation": install_plan,
        }
        plan["plan_id"] = "UPLAN-" + _digest(plan)
        return plan

    def _last_closed(self) -> Any:
        path = self.maintenance.root / "last-closed.json"
        if not path.exists():
            return None
        if path.is_symlink() or not path.is_file() or path.stat().st_size > 65536:
            raise RuntimeUpgradeError("upgrade_journal_invalid", "维护修订记录不安全")
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(value, dict) or set(value) != {"upgrade_id", "state"}:
                raise ValueError
            return value
        except (OSError, ValueError, TypeError) as error:
            raise RuntimeUpgradeError("upgrade_journal_invalid", "维护修订记录损坏") from error

    def _close(self, journal: dict[str, Any]) -> dict[str, Any]:
        self._save(journal)
        write_maintenance_json(self.maintenance.root / "last-closed.json", {"upgrade_id": journal["upgrade_id"], "state": journal["state"]})
        self.maintenance.finish(journal["upgrade_id"])
        return journal

    def check(self, *, installation: Mapping[str, Any] | None = None) -> dict[str, Any]:
        self.maintenance.assert_available()
        return self._inspect(installation)



    def operations(self) -> dict[str, Any]:
        records = self.maintenance.unclosed_operations()
        return {
            "schema_version": "strixnova.operation-recovery-catalog.v1", "project": str(self.project),
            "operations": [{**record, "stop_evidence_scope": {
                "kind": "project_operation", "project": str(self.project),
                "operation_id": record["operation_id"], "record_sha256": record["record_sha256"],
            }} for record in records],
            "may_have_more": len(records) == 100, "writes_performed": False,
        }

    def resolve_operation(self, operation_id: str, evidence: dict[str, Any]) -> dict[str, Any]:
        return self.maintenance.resolve_operation(operation_id, evidence)

    @staticmethod
    def plan_view(plan: Mapping[str, Any]) -> dict[str, Any]:
        fields = ("schema_version", "project", "plan_id", "source_formats", "target_formats", "target_runtime", "requires_maintenance_window", "writes_performed", "maintenance_revision")
        return {
            "project_identity": plan.get("project_identity"),
            **{key: plan[key] for key in fields},
            "asset_count": len(plan["assets"]),
            "asset_bytes": sum(value["size_bytes"] for value in plan["assets"].values()),
            "record_counts": {kind: source["counts"] for kind, source in plan["sources"].items()},
            "installation": plan.get("installation"),
        }

    @staticmethod
    def status_view(journal: Mapping[str, Any]) -> dict[str, Any]:
        fields = ("schema_version", "project", "upgrade_id", "state", "backup_directory", "created_at", "completed_at", "restored_at", "business_records_preserved", "failure", "runtime_selection", "restored_runtime", "host_reload_required", "entrypoint_validation", "aborted_before_source_change")
        state = journal.get("state")
        return {
            **{key: journal[key] for key in fields if key in journal},
            "recovery_modes": ["resume", "restore"] if state in {"verified", "switching"} else ["restore"] if state in {"prepared", "backed_up", "fencing", "restoring", "completed"} else [],
        }

    def status(self, upgrade_id: str | None = None) -> dict[str, Any]:
        self.maintenance._safe_root()
        if upgrade_id is None:
            active = self.maintenance.status()
            upgrade_id = active.get("upgrade_id")
            if upgrade_id is None:
                return {"state": "clear", "upgrade_id": None}
        try:
            return self.maintenance.read_upgrade_record(upgrade_id)
        except MaintenanceError as error:
            raise RuntimeUpgradeError(error.code, str(error), details=error.details) from error

    def _save(self, journal: dict[str, Any]) -> None:
        self.maintenance._safe_root()
        directory = self.maintenance.root / journal["upgrade_id"]
        if directory.is_symlink() or directory.is_junction() or (directory.exists() and not directory.is_dir()):
            raise RuntimeUpgradeError("upgrade_journal_invalid", "升级会话目录必须是受控普通目录")
        journal["journal_sha256"] = _digest({key: value for key, value in journal.items() if key != "journal_sha256"})
        write_maintenance_json(directory / "journal.json", journal)

    def _existing_attempt(self, plan: Mapping[str, Any], upgrade_id: str) -> dict[str, Any] | None:
        self.maintenance._safe_root()
        directory = self.maintenance.root / upgrade_id
        if directory.is_symlink() or directory.is_junction():
            raise RuntimeUpgradeError("upgrade_journal_invalid", "升级会话目录不能通过链接访问")
        if not directory.exists():
            return None
        if not directory.is_dir() or not (directory / "journal.json").is_file():
            raise RuntimeUpgradeError("upgrade_directory_occupied", "升级目录已被没有完整记录的内容占用")
        previous = self.status(upgrade_id)
        if dict(plan) != previous["plan"] and dict(plan) != self.plan_view(previous["plan"]):
            raise RuntimeUpgradeError("upgrade_plan_invalid", "重复请求必须与原升级计划完全一致")
        if previous["state"] == "completed":
            return previous
        raise RuntimeUpgradeError("upgrade_recovery_required", "该升级未完成或已中止，请查看状态并重新预检")

    def _abort_before_source_change(self, journal: dict[str, Any]) -> dict[str, Any]:
        """Close an attempt that has not fenced or replaced any source file."""
        if journal["state"] not in {"prepared", "backed_up", "aborted"}:
            raise RuntimeUpgradeError("upgrade_recovery_required", "已经改变源存储的尝试必须按恢复记录处理")
        journal["state"] = "aborted"
        journal["aborted_before_source_change"] = not journal.get("source_fences_removed", False)
        journal["aborted_before_replacement"] = True
        journal.setdefault("aborted_at", datetime.now(timezone.utc).isoformat())
        self._save(journal)
        active = self.maintenance.status()
        if active["state"] == "clear" or active.get("upgrade_id") == journal["upgrade_id"]:
            write_maintenance_json(self.maintenance.root / "last-closed.json", {"upgrade_id": journal["upgrade_id"], "state": "aborted"})
            if active["state"] != "clear":
                self.maintenance.finish(journal["upgrade_id"])
        return journal

    def _abort_fenced_sources(self, journal: dict[str, Any]) -> dict[str, Any]:
        """Undo only our guards before any candidate was switched in.

        An activity change observed during an interrupted maintenance attempt must
        remain recorded. Restoring an earlier business snapshot would lose it.
        """
        self.maintenance.begin(journal["upgrade_id"])
        current_sources = self._sources()
        if not set(journal["plan"]["sources"]) <= set(current_sources):
            raise RuntimeUpgradeError("upgrade_recovery_conflict", "源数据库已经缺失，不能把单纯解除保护当作恢复")
        for kind, original in journal["plan"]["sources"].items():
            current = _database_snapshot(current_sources[kind], kind)
            schema = [entry for entry in current["schema"] if not entry["name"].startswith(MAINTENANCE_TRIGGER_PREFIX)]
            extras = [entry for entry in current["schema"] if entry["name"].startswith(MAINTENANCE_TRIGGER_PREFIX)]
            tables = {entry["name"] for entry in original["schema"] if entry["type"] == "table"}
            expected_guards = write_guard_definitions(tables, temporary=True)
            if current["format"] != original["format"] or schema != original["schema"] or any(entry not in expected_guards for entry in extras):
                raise RuntimeUpgradeError("upgrade_recovery_conflict", "源结构已经出现不属于本次临时保护的变化")
        for kind in journal["plan"]["sources"]:
            with closing(sqlite3.connect(current_sources[kind], timeout=0.5)) as connection:
                for (name,) in connection.execute("SELECT name FROM sqlite_master WHERE type='trigger'").fetchall():
                    if name.startswith(MAINTENANCE_TRIGGER_PREFIX):
                        connection.execute('DROP TRIGGER "' + name.replace('"', '""') + '"')
                connection.commit()
        journal["state"] = "aborted"
        journal["source_fences_removed"] = True
        return self._abort_before_source_change(journal)

    def apply(self, plan: Mapping[str, Any]) -> dict[str, Any]:
        if not isinstance(plan, Mapping) or not isinstance(plan.get("plan_id"), str):
            raise RuntimeUpgradeError("upgrade_plan_invalid", "必须提供预检返回的完整计划")
        if plan.get("schema_version") != "strixnova.runtime-upgrade-plan.v1" or plan.get("project") != str(self.project):
            raise RuntimeUpgradeError("upgrade_plan_invalid", "升级计划缺少正确的公开合同与项目绑定")
        if any(plan.get(key) is not None and not isinstance(plan[key], Mapping) for key in ("installation",)):
            raise RuntimeUpgradeError("upgrade_plan_invalid", "升级来源、安装或停止证据必须使用预检返回的对象")
        upgrade_id = "UPGRADE-" + hashlib.sha256(plan["plan_id"].encode()).hexdigest()[:24].upper()
        directory = self.maintenance.root / upgrade_id
        previous = self._existing_attempt(plan, upgrade_id)
        if previous is not None:
            return previous
        installation = plan.get("installation")
        install_request = installation.get("request") if isinstance(installation, Mapping) else None
        inspected = self.check(installation=install_request)
        if dict(plan) != inspected and dict(plan) != self.plan_view(inspected):
            raise RuntimeUpgradeError("upgrade_plan_stale", "源数据或目标构建已经变化，请重新预检")
        plan = inspected
        prepared = None
        if installation is not None:
            manager = ManagedInstallation(plan["installation"]["installation_root"], self.project)
            prepared = manager.prepare(plan["installation"]["target"], builder_python=plan["installation"]["builder_python"], wheelhouse=plan["installation"]["wheelhouse"])
            if prepared["runtime"]["build_sha256"] != runtime_identity()["build_sha256"]:
                return self._delegate_apply(plan, prepared)
        with self.maintenance.executor():
            previous = self._existing_attempt(plan, upgrade_id)
            if previous is not None:
                return previous
            journal: dict[str, Any] = {
                "schema_version": "strixnova.runtime-upgrade-journal.v1", "project": str(self.project),
                "upgrade_id": upgrade_id, "state": "prepared", "plan": dict(plan),
                "backup_directory": str(directory / "backup"), "created_at": datetime.now(timezone.utc).isoformat(),
                "replacements": [],
                "prepared_installation": prepared,
            }
            self._save(journal)
            try:
                self.maintenance.begin(upgrade_id)
                if self._inspect(install_request) != dict(plan):
                    raise RuntimeUpgradeError("upgrade_plan_stale", "已有操作结束后源数据变化，请恢复维护并重新预检")
                if {kind: _database_snapshot(path, kind) for kind, path in self._sources().items()} != plan["sources"] or self._assets() != plan["assets"]:
                    raise RuntimeUpgradeError("upgrade_plan_stale", "关闭旧程序准入时来源已变化，保持事实并重新预检")
                for path in self._sources().values():
                    self._quiesce(path)
                required = sum(path.stat().st_size for path in self._sources().values()) * 3 + sum(value["size_bytes"] for value in plan["assets"].values()) * 2
                if shutil.disk_usage(self.project).free < required + 1024 * 1024:
                    raise RuntimeUpgradeError("upgrade_space_insufficient", "备份和转换空间不足")
                backup = directory / "backup"
