            for kind, original in journal["plan"]["sources"].items():
                if kind not in names:
                    raise RuntimeUpgradeError("upgrade_journal_invalid", "恢复清单包含未知数据库")
                current = _database_snapshot(self.project / ".strixnova" / names[kind], kind)
